CREATE TABLE enterprise_continuity_plans(id TEXT PRIMARY KEY NOT NULL,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,process TEXT NOT NULL,bia_ref TEXT NOT NULL,criticality TEXT NOT NULL,owner TEXT NOT NULL,reviewer TEXT NOT NULL,crisis_lead TEXT NOT NULL,rto_hours REAL NOT NULL,rpo_hours REAL NOT NULL,mtpd_hours REAL NOT NULL,dependencies TEXT NOT NULL,recovery_strategy TEXT NOT NULL,communication_plan TEXT NOT NULL,alternate_site TEXT,supplier_dependencies TEXT,minimum_staff INTEGER NOT NULL,review_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',version INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_by TEXT NOT NULL,updated_at TEXT NOT NULL,approved_by TEXT,approved_at TEXT,activated_at TEXT,retired_at TEXT);
CREATE INDEX enterprise_continuity_plan_status_idx ON enterprise_continuity_plans(status,criticality,review_date);
CREATE TABLE enterprise_continuity_exercises(id TEXT PRIMARY KEY NOT NULL,code TEXT NOT NULL UNIQUE,plan_id TEXT NOT NULL,type TEXT NOT NULL,scheduled_date TEXT NOT NULL,scenario TEXT NOT NULL,facilitator TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'planned',outcome TEXT,actual_recovery_hours REAL,actual_data_loss_hours REAL,rto_breached INTEGER NOT NULL DEFAULT 0,rpo_breached INTEGER NOT NULL DEFAULT 0,observations TEXT,root_cause TEXT,evidence_reference TEXT,evidence_sha256 TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL,completed_by TEXT,completed_at TEXT);
CREATE INDEX enterprise_continuity_exercise_plan_idx ON enterprise_continuity_exercises(plan_id,scheduled_date,status);
CREATE TABLE enterprise_continuity_gaps(id TEXT PRIMARY KEY NOT NULL,exercise_id TEXT NOT NULL,plan_id TEXT NOT NULL,severity TEXT NOT NULL,title TEXT NOT NULL,owner TEXT NOT NULL,reviewer TEXT NOT NULL,due_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',evidence_reference TEXT,evidence_sha256 TEXT,created_at TEXT NOT NULL,closed_by TEXT,closed_at TEXT);
CREATE INDEX enterprise_continuity_gap_status_idx ON enterprise_continuity_gaps(status,severity,due_date);
CREATE TABLE enterprise_continuity_events(id TEXT PRIMARY KEY NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,action TEXT NOT NULL,detail TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX enterprise_continuity_event_idx ON enterprise_continuity_events(entity_id,created_at);
